    refs: ["Lev 19:32-34", "Prov 14:31", "Matt 5:22", "Mark 10:13-16", "John 4:7-27", "Rom 12:10", "1 Pet 2:17", "1 Pet 3:7", "James 2:1-9"],
    science: "",
